// ============================================================
// Karim Benali — Routeur déterministe. On route, on ne pense pas.
// ============================================================
const body      = $input.item.json.body || $input.item.json;
const eventType = (body.type  || '').toUpperCase();
const table     = body.table  || '';
const record    = body.record     || {};
const oldRecord = body.old_record || {};

const targets = [];

// ---- LEADS -------------------------------------------------
if (table === 'leads') {
  if (eventType === 'INSERT') {
    targets.push({ agent: 'alex',  tier: 1, action: 'new_lead',
      webhookPath: '/webhook/agent-alex',
      payload: { trigger: 'lead_insert', lead: record } });
  }
  if (Number(record.score) >= 75) {
    targets.push({ agent: 'julie', tier: 1, action: 'hot_lead_qualification',
      webhookPath: '/webhook/agent-julie',
      payload: { trigger: 'score_threshold', lead: record, score: record.score } });
  }
  if (record.status === 'signed' && oldRecord.status !== 'signed') {
    targets.push({ agent: 'sarah', tier: 1, action: 'lead_signed_onboarding',
      webhookPath: '/webhook/agent-sarah',
      payload: { trigger: 'lead_signed', lead: record } });
  }
}

// ---- PROJECTS ----------------------------------------------
if (table === 'projects' && eventType === 'UPDATE' && record.status !== oldRecord.status) {
  const s = record.status;
  if (s === 'brief_completed') {
    targets.push({ agent: 'salma', tier: 1, action: 'brief_completed_start_blueprint',
      webhookPath: '/webhook/agent-salma',
      payload: { trigger: 'brief_completed', project: record } });
  }
  if (s === 'blueprint_approved') {
    targets.push({ agent: 'nabil', tier: 1, action: 'blueprint_approved_start_dev',
      webhookPath: '/webhook/agent-nabil',
      payload: { trigger: 'blueprint_approved', project: record } });
    targets.push({ agent: 'lina',  tier: 1, action: 'blueprint_approved_start_design',
      webhookPath: '/webhook/agent-lina',
      payload: { trigger: 'blueprint_approved', project: record } });
  }
  if (s === 'copy_design_done') {
    targets.push({ agent: 'yanis', tier: 1, action: 'copy_design_done_qa',
      webhookPath: '/webhook/agent-yanis',
      payload: { trigger: 'copy_design_done', project: record } });
  }
  if (s === 'preview_ready') {
    targets.push({ agent: 'victor', tier: 1, action: 'preview_ready_delivery',
      webhookPath: '/webhook/agent-victor',
      payload: { trigger: 'preview_ready', project: record } });
  }
}

// ---- INVOICES ----------------------------------------------
if (table === 'invoices' && record.status === 'paid' && oldRecord.status !== 'paid') {
  targets.push({ agent: 'amir', tier: 2, action: 'invoice_paid_notification',
    webhookPath: '/webhook/agent-amir-notify',
    payload: { trigger: 'invoice_paid', invoice: record } });
}

// ---- Aucun match -------------------------------------------
if (targets.length === 0) {
  return [{ json: {
    _skip: true, _reason: 'no_routing_match',
    table, eventType, recordStatus: record.status
  }}];
}

return targets.map(t => ({ json: t }));

return [{ json: {
  agent: 'omar', tier: 1, action: 'daily_report_23h',
  webhookPath: '/webhook/agent-omar',
  payload: { trigger: 'cron_23h00', timestamp: new Date().toISOString() }
}}];

return [{ json: {
  agent: 'alex', tier: 1, action: 'weekly_prospection_monday',
  webhookPath: '/webhook/agent-alex',
  payload: { trigger: 'cron_lundi_08h00', timestamp: new Date().toISOString() }
}}];

// Appel HTTP de l'agent + construction du contexte pour agent_logs
const ctx = $input.item.json;
const N8N_BASE = $env['N8N_WEBHOOK_BASE_URL'] || 'http://localhost:5678';
const url = N8N_BASE + ctx.webhookPath;

const t0 = Date.now();
let httpStatus = 0;
let output = {};

try {
  const resp = await $http.request({
    method: 'POST',
    url,
    body: ctx.payload,
    json: true,
    timeout: 30000
  });
  httpStatus = resp.statusCode || 200;
  output = resp.body || {};
} catch (err) {
  httpStatus = err.statusCode || 500;
  output = { error: err.message };
}

const duration_ms = Date.now() - t0;
const status = (httpStatus >= 200 && httpStatus < 300) ? 'success' : 'error';

return [{ json: {
  agent_id:      ctx.agent,
  action:        ctx.action,
  input:         ctx.payload,
  output:        { httpStatus, body: output },
  tier:          ctx.tier || 1,
  duration_ms,
  status,
  error_message: status === 'error' ? JSON.stringify(output) : null
}}];
